import type {DefinitionOrReference} from '@github-ui/code-nav'
import {useRuntimeEnvironment} from '@github-ui/ssr-utils/use-runtime-environment'
import {clsx} from 'clsx'
import {createPortal} from 'react-dom'

import {useCurrentStyledBlob} from '../../../../hooks/CurrentStyledBlob'
import {scrollLineIntoView} from '../../../../hooks/use-scroll-line-into-view'
import styles from './ScrollMarks.module.css'
import {scrollMarksContainerID} from './ScrollMarksContainer'

interface ScrollMarksProps {
  definitionsOrReferences: DefinitionOrReference[]
}

export default function ScrollMarks({definitionsOrReferences}: ScrollMarksProps) {
  const totalLineCount = useCurrentStyledBlob().rawLines?.length ?? 0
  const {isBrowser} = useRuntimeEnvironment()
  const container = isBrowser ? document.getElementById(scrollMarksContainerID) : null
  const windowHasVerticalScroll = isBrowser ? document.body.scrollHeight > window.innerHeight : false

  if (!container) return null

  return createPortal(
    <ScrollMarksDesign
      totalLineCount={totalLineCount}
      windowHasVerticalScroll={windowHasVerticalScroll}
      definitionsOrReferences={definitionsOrReferences}
    />,
    container,
  )
}

interface ScrollMarksDesignProps {
  definitionsOrReferences: DefinitionOrReference[]
  totalLineCount: number
  windowHasVerticalScroll: boolean
}

export function ScrollMarksDesign({
  definitionsOrReferences,
  totalLineCount,
  windowHasVerticalScroll,
}: ScrollMarksDesignProps) {
  // Do not show anything if the entire file contents are already visible
  if (!windowHasVerticalScroll) return null

  // Do not show anything if there are no results
  if (definitionsOrReferences.length === 0) return null

  const marks = definitionsOrReferences.map(result => ({
    // Strictly speaking, this does not take into account the height of the area above the code
    // lines, but what I've found is that even in extreme edge cases (a very short file with a
    // window that's short enough to add vertical scroll), the location of the mark is still good
    // enough to get you to the result if you scroll to it.
    location: result.lineNumber / totalLineCount,
    key: `find-in-file-mark:${result.path}:${result.lineNumber},${result.ident.start.column}`,
    line: result.lineNumber,
  }))

  // De-duplicate the marks based on location
  const seenLocations = new Set<number>()
  const dedupedMarks = marks.filter(mark => {
    if (seenLocations.has(mark.location)) return false
    seenLocations.add(mark.location)
    return true
  })

  return (
    <div data-testid="scroll-marks-parent" className={clsx('react-blob-scroll-marks', styles.scrollMarksParent)}>
      {dedupedMarks.map(mark => (
        <ScrollMark key={mark.key} onClick={() => scrollLineIntoView({line: mark.line})} markLocation={mark.location} />
      ))}
    </div>
  )
}

function ScrollMark({markLocation, onClick}: {markLocation: number; onClick: () => void}) {
  return (
    <button
      type="button"
      aria-label="Scroll to symbol"
      data-testid="scroll-mark"
      className={styles.scrollMark}
      onClick={onClick}
      style={{top: `${markLocation * 100}%`}}
    />
  )
}
